// SPDX-License-Identifier: MIT
//! Raw bindings of the Mesa interfaces the nvkmd backend implements and calls,
//! generated by `mesa/gen-nvkmd-bindings.py` from `wrapper.h` with the compile
//! flags of `nvkmd.c` in each target's NVK build: the nvkmd vtables and objects
//! (`nvkmd/nvkmd.h`), `vk_sync` types (`vk_sync.h`), `nv_device_info`,
//! `util_vma_heap`, libdrm's device and version records, and the functions the
//! backend calls. `vk_device` and `vk_object_base` stay opaque; the members the
//! backend reaches in them and in `nvk_device` are the `NVKMD_SYS_*` offsets.
//!
//! Layouts differ per target (pointer width, libc), so each target has its own
//! file, and bindgen's layout assertions check every struct when that target
//! compiles. No logic.
#![no_std]

#[cfg(all(target_arch = "x86_64", target_os = "android"))]
#[path = "x86_64_linux_android.rs"]
#[expect(
    missing_docs,
    missing_debug_implementations,
    non_camel_case_types,
    non_snake_case,
    clippy::allow_attributes,
    clippy::allow_attributes_without_reason,
    clippy::pub_underscore_fields,
    clippy::unreadable_literal,
    reason = "bindgen output keeps the C names and layouts; the headers document them"
)]
mod bindings;
#[cfg(all(target_arch = "x86", target_os = "android"))]
#[path = "i686_linux_android.rs"]
#[expect(
    missing_docs,
    missing_debug_implementations,
    non_camel_case_types,
    non_snake_case,
    clippy::allow_attributes,
    clippy::allow_attributes_without_reason,
    clippy::pub_underscore_fields,
    clippy::unreadable_literal,
    reason = "bindgen output keeps the C names and layouts; the headers document them"
)]
mod bindings;
#[cfg(all(target_arch = "x86_64", target_os = "linux", target_env = "gnu"))]
#[path = "x86_64_linux_gnu.rs"]
#[expect(
    missing_docs,
    missing_debug_implementations,
    non_camel_case_types,
    non_snake_case,
    clippy::allow_attributes,
    clippy::allow_attributes_without_reason,
    clippy::pub_underscore_fields,
    clippy::unreadable_literal,
    reason = "bindgen output keeps the C names and layouts; the headers document them"
)]
mod bindings;

pub use bindings::*;

#[cfg(not(any(
    all(target_arch = "x86_64", target_os = "android"),
    all(target_arch = "x86", target_os = "android"),
    all(target_arch = "x86_64", target_os = "linux", target_env = "gnu"),
)))]
compile_error!("nvkmd-sys has bindings for x86_64/i686 Android and x86_64 Linux (glibc) only");
